{
  "title": "The Mirror Rescue of Ruinfall",
  "gate_token": "4Lk8Yyjj2tZ0kZi-qTMQlg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined city.",
      "visual_description": "A cracked marble plaza under a grey sky, broken royal banners hanging from collapsed arches. Mara spreads a weathered map across a fallen pillar, her brass compass glinting.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The glass diver surfaces from a shattered fountain.",
      "visual_description": "A clear diving helmet emerges from murky water in a dry fountain, reflecting the city's broken towers. The diver climbs out, coat dripping with oily rainbows.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning.",
      "visual_description": "Inside a collapsed guardhouse, the oracle lamp sits on a dusty shelf. Its single flame-eye glows amber as it speaks, casting long shadows on the walls.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector snores by the castle gates.",
      "visual_description": "The ruined castle gates are slightly ajar. Nearby, a man in ink-stained robes dozes against a barrel, using a ledger as a pillow, stamped papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox scouts ahead through rubble.",
      "visual_description": "A small clockwork fox picks its way over broken stone, key-wind tail ticking. Its blue glass eyes scan the debris ahead, ears rotating like sensors.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara leads the team past the castle gates.",
      "visual_description": "Mara gestures toward the dark opening, her map in hand. The glass diver follows, and the oracle lamp floats behind them, casting a warm glow on the ancient iron.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Inside the courtyard, a cursed tower looms.",
      "visual_description": "A twisted obsidian tower rises from the courtyard center, windows flickering with eerie light. Broken royal banners hang from its sides, and the ground is covered in shattered glass.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp warns of a trap in the tower.",
      "visual_description": "The lamp's eye becomes a slit, its flame dimming. Mara and the glass diver pause at the tower's base as shadows move on the walls inside.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox triggers a hidden snare.",
      "visual_description": "The fox steps on a pressure plate; a net of rusted chains drops from above. The fox dodges, but the noise echoes through the tower hall.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector wakes and wanders in.",
      "visual_description": "Roused by the clatter, the tax collector stumbles into the tower, rubbing his eyes, ledger still under his arm, papers fluttering behind him.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Mara finds a secret door behind a tapestry.",
      "visual_description": "Mara pushes aside a frayed banner depicting a sunburst, revealing a door made of polished, mirror-like metal. The glass diver steps forward, intrigued.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver passes through the magic door.",
      "visual_description": "The diver touches the door; it ripples like water. The diver swims through its surface, the helmet reflecting the room behind, entering a dark corridor beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp illuminates the escape route.",
      "visual_description": "The lamp floats into the corridor, its light revealing a path winding past old statues and rusted armors. Mara follows, marking her map.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Armored patrols march through the streets above.",
      "visual_description": "Through a grate in the corridor ceiling, the group sees booted feet marching in unison, metal-clad legs passing, the sound of rhythmic footsteps echoing.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector falls behind.",
      "visual_description": "The tax collector stops to pick up a dropped stamp, yawning, as the patrols' footsteps grow louder. The tin fox tugs at his trouser cuff to hurry him.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The group reaches the bridge at the city's edge.",
      "visual_description": "A long stone bridge spans a dry riverbed, broken statues lining its sides. The far end is the only way out, but the bridge is partially collapsed.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The tin fox holds the bridge as the others cross.",
      "visual_description": "The fox turns to face the approaching patrols, its clockwork tail winding faster, blue eyes bright, standing guard at the bridge's near end.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Everyone escapes beyond the bridge.",
      "visual_description": "Mara, the glass diver, the oracle lamp, and the sleeping tax collector cross the final gap. The tin fox dashes across last, joining them as the bridge crumbles behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

